import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)

    try:
        num_test_cases = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(num_test_cases):
        n = int(next(iterator))
        k = int(next(iterator))
        l = int(next(iterator))

        d = []
        for _ in range(n):
            d.append(int(next(iterator)))

        if any(x > l for x in d):
            results.append("No")
            continue

        current_tide = 0
        possible = True

        for depth in d:
            max_tide = l - depth

            if max_tide < 0:
                possible = False
                break

            if current_tide > max_tide:
                if k <= max_tide:
                    current_tide = max_tide
                else:
                    if max_tide >= k:
                        current_tide = max_tide
                    else:
                        if current_tide <= max_tide + 2 * k:
                            current_tide = max_tide
                        else:
                            possible = False
                            break
            else:
                current_tide += 1

            if current_tide >= 2 * k:
                current_tide %= (2 * k)

        if possible:
            results.append("Yes")
        else:
            results.append("No")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
